function C:bloom()
  Debug.Log(CONCAT("light:", self.light))
  self.light = self.light + 1
  if self.light <= 2150 and self.light > 2000 then
    PostEffectManager:SetShaderWeight_1((self.light - 2000) / 150)
  end
end

function C:StartScenario()
  if not coroutine.isyieldable() then spawn(C.StartScenario, self) return end
  AudioManager:PlayBgmByType("BGM_ending_ginga", false)
  C.super.StartScenario(self)
  self._Live:HaishinClean()
  WindowManager:CloseApp("LiveDark")
  EventManager:ClearEventQueue()
  AchievementStatsUpdater.UpdateStats("Ending_Ginga")
  NotificationManager:osimai()
end

return C
